"""
Dataset manifest loading and conversion for the offline ore scene pipeline.

Two provenance classes are supported in S1:

* ``synthetic`` — generated by :mod:`jcheng_perception_scene.synthetic`;
* ``public`` — converted from a dataset that ships COCO polygon annotations.

Recorded real ore with human instance masks is a future class and is not
claimed here.
"""

import dataclasses
import datetime
import json
import os
from typing import Any, Dict, List, Optional

import cv2
import numpy as np

from .types import (
    DATASET_SCHEMA_VERSION,
    ERROR_INPUT_DATASET,
    SceneError,
    sha256_file,
)


@dataclasses.dataclass
class DatasetScene:
    """One scene entry from a dataset manifest."""

    scene_id: str
    image_path: str
    mask_path: str
    width: int
    height: int
    timestamp_ns: int
    frame_id: str
    attributes: Dict[str, Any]
    instances: List[Dict[str, Any]]


@dataclasses.dataclass
class Dataset:
    """A loaded dataset manifest plus resolved paths."""

    root: str
    manifest_path: str
    manifest: Dict[str, Any]
    scenes: List[DatasetScene]

    @property
    def dataset_id(self):
        """Return the dataset identifier."""
        return str(self.manifest['dataset_id'])

    @property
    def source(self):
        """Return the provenance class (synthetic/public/recorded)."""
        return str(self.manifest['source'])

    @property
    def annotation_method(self):
        """Return how the ground truth was produced."""
        return str(self.manifest['annotation_method'])

    @property
    def license(self):
        """Return the dataset license identifier."""
        return str(self.manifest.get('license', 'unknown'))


def _resolve(root, path):
    if os.path.isabs(path):
        return path
    return os.path.join(root, path)


def load_dataset(root):
    """Load and structurally validate ``<root>/dataset.json``."""
    manifest_path = os.path.join(root, 'dataset.json')
    if not os.path.isfile(manifest_path):
        raise ValueError('dataset manifest not found: %s' % manifest_path)
    with open(manifest_path, 'r', encoding='utf-8') as handle:
        manifest = json.load(handle)
    if not isinstance(manifest, dict):
        raise ValueError('dataset manifest root must be an object')
    required = (
        'schema_version', 'dataset_id', 'source', 'annotation_method',
        'license', 'scenes',
    )
    for key in required:
        if key not in manifest:
            raise ValueError('dataset manifest missing %s' % key)
    if manifest['schema_version'] != DATASET_SCHEMA_VERSION:
        raise ValueError('unsupported dataset schema: %s' %
                         manifest['schema_version'])
    if manifest['source'] not in ('synthetic', 'public', 'recorded'):
        raise ValueError('unsupported dataset source: %s' % manifest['source'])
    if not isinstance(manifest['scenes'], list):
        raise ValueError('dataset scenes must be a list')

    scenes = []
    seen = set()
    for entry in manifest['scenes']:
        for key in ('scene_id', 'image', 'mask', 'width', 'height',
                    'instances'):
            if key not in entry:
                raise ValueError('scene missing %s' % key)
        scene_id = str(entry['scene_id'])
        if scene_id in seen:
            raise ValueError('duplicate scene_id: %s' % scene_id)
        seen.add(scene_id)
        instances = entry['instances']
        if not isinstance(instances, list):
            raise ValueError('scene %s instances must be a list' % scene_id)
        for instance in instances:
            if 'instance_id' not in instance or 'mask_index' not in instance:
                raise ValueError(
                    'scene %s has an instance without id/mask_index' %
                    scene_id)
        scenes.append(DatasetScene(
            scene_id=scene_id,
            image_path=_resolve(root, entry['image']),
            mask_path=_resolve(root, entry['mask']),
            width=int(entry['width']),
            height=int(entry['height']),
            timestamp_ns=int(entry.get('timestamp_ns', 0)),
            frame_id=str(entry.get('frame_id', 'camera_color_optical_frame')),
            attributes=dict(entry.get('attributes', {})),
            instances=list(instances),
        ))
    return Dataset(
        root=os.path.abspath(root),
        manifest_path=os.path.abspath(manifest_path),
        manifest=manifest,
        scenes=scenes,
    )


def validate_dataset_files(dataset, check_hashes=True):
    """Return a list of :class:`SceneError` for missing or corrupt files."""
    errors = []
    for scene in dataset.scenes:
        if not os.path.isfile(scene.image_path):
            errors.append(SceneError(
                code=ERROR_INPUT_DATASET,
                message='missing image: %s' % scene.image_path,
                stage='dataset',
                context={'scene_id': scene.scene_id},
            ))
            continue
        image = cv2.imread(scene.image_path, cv2.IMREAD_COLOR)
        if image is None:
            errors.append(SceneError(
                code=ERROR_INPUT_DATASET,
                message='unreadable image: %s' % scene.image_path,
                stage='dataset',
                context={'scene_id': scene.scene_id},
            ))
            continue
        if image.shape[1] != scene.width or image.shape[0] != scene.height:
            errors.append(SceneError(
                code=ERROR_INPUT_DATASET,
                message='image size %dx%d != manifest %dx%d' % (
                    image.shape[1], image.shape[0], scene.width, scene.height),
                stage='dataset',
                context={'scene_id': scene.scene_id},
            ))
        if not os.path.isfile(scene.mask_path):
            errors.append(SceneError(
                code=ERROR_INPUT_DATASET,
                message='missing mask: %s' % scene.mask_path,
                stage='dataset',
                context={'scene_id': scene.scene_id},
            ))
            continue
        if check_hashes:
            expected = scene.attributes.get('mask_sha256')
            if expected and sha256_file(scene.mask_path) != expected:
                errors.append(SceneError(
                    code=ERROR_INPUT_DATASET,
                    message='mask sha256 mismatch: %s' % scene.mask_path,
                    stage='dataset',
                    context={'scene_id': scene.scene_id},
                ))
    return errors


def load_ground_truth(scene):
    """Load one scene's uint16 instance mask and validate the labels."""
    mask = cv2.imread(scene.mask_path, cv2.IMREAD_UNCHANGED)
    if mask is None:
        raise ValueError('cannot read ground-truth mask: %s' % scene.mask_path)
    if mask.ndim != 2:
        raise ValueError('ground-truth mask must be single-channel')
    if mask.shape[0] != scene.height or mask.shape[1] != scene.width:
        raise ValueError('ground-truth mask shape does not match manifest')
    if mask.dtype != np.uint16:
        if mask.dtype != np.uint8:
            raise ValueError('ground-truth mask must be uint8 or uint16')
    expected = set(int(instance['mask_index']) for instance in scene.instances)
    present = set(int(value) for value in np.unique(mask) if int(value) != 0)
    if not present.issubset(expected):
        raise ValueError(
            'mask has labels without manifest entries: %s' %
            sorted(present - expected))
    return mask.astype(np.uint16, copy=False)


def read_predictions(path, expected_schema=None):
    """Read a JSONL scene-state export and return a list of records."""
    from .types import SCENE_SCHEMA_VERSION
    expected_schema = expected_schema or SCENE_SCHEMA_VERSION
    records = []
    with open(path, 'r', encoding='utf-8') as handle:
        for line_number, line in enumerate(handle, start=1):
            line = line.strip()
            if not line:
                continue
            try:
                record = json.loads(line)
            except json.JSONDecodeError as error:
                raise ValueError(
                    'invalid JSONL at line %d: %s' % (line_number, error))
            if record.get('schema_version') != expected_schema:
                raise ValueError(
                    'line %d has schema %r, expected %r' % (
                        line_number, record.get('schema_version'),
                        expected_schema))
            records.append(record)
    return records


def write_jsonl(path, records):
    """Write records as UTF-8 JSON Lines, one object per line."""
    os.makedirs(os.path.dirname(os.path.abspath(path)), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as handle:
        for record in records:
            handle.write(json.dumps(
                record, sort_keys=True, ensure_ascii=False))
            handle.write('\n')


def _rasterise_polygons(annotation, height, width):
    """Rasterise one COCO annotation into ``(bbox, local_mask)``.

    Only the annotation's bounding box is allocated; a full-resolution mask per
    annotation would be prohibitively slow on 5 MP images with >1000 stones.
    """
    segmentation = annotation.get('segmentation')
    if not isinstance(segmentation, list) or not segmentation:
        raise ValueError(
            'annotation %s has no polygon segmentation (RLE is not '
            'supported in S1)' % annotation.get('id'))
    polygons = []
    all_points = []
    for polygon in segmentation:
        if not isinstance(polygon, list) or len(polygon) < 6:
            raise ValueError(
                'annotation %s has an invalid polygon' % annotation.get('id'))
        points = np.asarray(polygon, dtype=np.float64).reshape(-1, 2)
        points[:, 0] = np.clip(points[:, 0], 0, width - 1)
        points[:, 1] = np.clip(points[:, 1], 0, height - 1)
        polygons.append(np.round(points).astype(np.int32))
        all_points.append(points)
    stacked = np.concatenate(all_points, axis=0)
    x0 = max(0, int(np.floor(stacked[:, 0].min())))
    y0 = max(0, int(np.floor(stacked[:, 1].min())))
    x1 = min(width - 1, int(np.ceil(stacked[:, 0].max())))
    y1 = min(height - 1, int(np.ceil(stacked[:, 1].max())))
    if x1 < x0 or y1 < y0:
        return None
    local = np.zeros((y1 - y0 + 1, x1 - x0 + 1), dtype=np.uint8)
    offset = np.array([x0, y0], dtype=np.int32)
    for points in polygons:
        cv2.fillPoly(local, [points - offset], 255)
    if not np.any(local):
        return None
    return (x0, y0, x1, y1), local > 0


def import_coco_dataset(coco_json, images_root, out_dir, dataset_id,
                        source='public', license_id='unknown',
                        citation=None, source_url=None, category_names=None,
                        image_limit=None, image_offset=0, created_at=None):
    """Convert COCO polygon annotations into the internal dataset layout.

    Images are referenced by absolute path, not copied. Masks are rasterised
    into ``<out_dir>/masks`` so evaluation never depends on a COCO parser at
    run time. Crowd annotations (``iscrowd=1``) are skipped: COCO evaluation
    ignores them, and treating them as normal instances would corrupt counts.
    """
    with open(coco_json, 'r', encoding='utf-8') as handle:
        coco = json.load(handle)
    if not isinstance(coco, dict) or 'images' not in coco or \
            'annotations' not in coco:
        raise ValueError('not a COCO instance annotation file: %s' % coco_json)
    categories = {
        int(category['id']): str(category.get('name', category['id']))
        for category in coco.get('categories', [])
    }
    allowed = None
    if category_names:
        allowed = set(str(name) for name in category_names)
    by_image = {}
    skipped_crowd = 0
    for annotation in coco['annotations']:
        if int(annotation.get('iscrowd', 0)) == 1:
            skipped_crowd += 1
            continue
        image_id = annotation.get('image_id')
        by_image.setdefault(image_id, []).append(annotation)

    os.makedirs(os.path.join(out_dir, 'masks'), exist_ok=True)
    scenes = []
    skipped_images = []
    image_entries = coco['images']
    offset = max(0, int(image_offset))
    if image_limit is not None:
        image_entries = image_entries[
            offset:offset + max(0, int(image_limit))]
    else:
        image_entries = image_entries[offset:]
    for image_entry in image_entries:
        image_id = image_entry.get('id')
        file_name = image_entry.get('file_name')
        if file_name is None:
            skipped_images.append('image id %s has no file_name' % image_id)
            continue
        image_path = file_name
        if not os.path.isabs(image_path):
            image_path = os.path.join(images_root, file_name)
        image_path = os.path.abspath(image_path)
        image = cv2.imread(image_path, cv2.IMREAD_COLOR)
        if image is None:
            skipped_images.append('unreadable image: %s' % image_path)
            continue
        height, width = image.shape[:2]
        annotations = by_image.get(image_id, [])
        mask = np.zeros((height, width), dtype=np.uint16)
        metadata = []
        mask_index = 0
        for annotation in annotations:
            category = categories.get(int(annotation.get('category_id', -1)),
                                      'unknown')
            if allowed is not None and category not in allowed:
                continue
            rasterised = _rasterise_polygons(annotation, height, width)
            if rasterised is None:
                continue
            (x0, y0, x1, y1), local = rasterised
            mask_index += 1
            # Overlapping COCO polygons are flattened in annotation order.
            # This is an explicit S1 limitation: the internal dataset stores
            # visible label maps, not independent per-instance masks.
            region = mask[y0:y1 + 1, x0:x1 + 1]
            region[local] = mask_index
            metadata.append((
                mask_index, category, annotation.get('id')))

        instances = []
        if mask_index:
            counts = np.bincount(mask.ravel(), minlength=mask_index + 1)
            rows, columns = np.nonzero(mask)
            labels = mask[rows, columns]
            x0 = np.full(mask_index + 1, width, dtype=np.int64)
            y0 = np.full(mask_index + 1, height, dtype=np.int64)
            x1 = np.full(mask_index + 1, -1, dtype=np.int64)
            y1 = np.full(mask_index + 1, -1, dtype=np.int64)
            np.minimum.at(x0, labels, columns)
            np.minimum.at(y0, labels, rows)
            np.maximum.at(x1, labels, columns)
            np.maximum.at(y1, labels, rows)
            for ordinal, (index, category, source_id) in enumerate(metadata):
                area = int(counts[index])
                if area == 0:
                    continue
                instances.append({
                    'instance_id': '%s:%04d' % (str(image_id), index),
                    'mask_index': int(index),
                    'category': category,
                    'area_px': area,
                    'occlusion_ratio': None,
                    'contact_px': None,
                    'contact_ratio': None,
                    'bbox_xyxy': [
                        int(x0[index]), int(y0[index]),
                        int(x1[index]), int(y1[index]),
                    ],
                    'stratum': 'unlabelled',
                    'source_annotation_id': source_id,
                    'source_annotation_ordinal': ordinal,
                })
        stem = os.path.splitext(os.path.basename(image_path))[0]
        scene_id = '%s-%s' % (str(dataset_id), stem)
        mask_name = 'masks/%s.png' % scene_id
        mask_path = os.path.join(out_dir, mask_name)
        if not cv2.imwrite(mask_path, mask):
            raise RuntimeError('failed to write %s' % mask_path)
        scenes.append({
            'scene_id': scene_id,
            'image': image_path,
            'mask': mask_name,
            'width': int(width),
            'height': int(height),
            'timestamp_ns': 0,
            'frame_id': 'camera_color_optical_frame',
            'attributes': {
                'source': source,
                'n_instances': len(instances),
                'empty': len(instances) == 0,
                'occlusion_class': 'unlabelled',
                'mask_sha256': sha256_file(mask_path),
            },
            'instances': instances,
        })

    if created_at is None:
        created_at = datetime.datetime.now(
            datetime.timezone.utc).replace(microsecond=0).isoformat()
    manifest = {
        'schema_version': DATASET_SCHEMA_VERSION,
        'dataset_id': str(dataset_id),
        'source': source,
        'annotation_method': 'dataset_provided_coco_polygons',
        'license': str(license_id),
        'citation': citation,
        'source_url': source_url,
        'original_annotations': os.path.abspath(coco_json),
        'original_annotations_sha256': sha256_file(coco_json),
        'created_at': created_at,
        'skipped_crowd_annotations': int(skipped_crowd),
        'skipped_images': skipped_images,
        'category_names': sorted(set(
            instance['category'] for scene in scenes
            for instance in scene['instances'])),
        'scenes': scenes,
    }
    manifest_path = os.path.join(out_dir, 'dataset.json')
    with open(manifest_path, 'w', encoding='utf-8') as handle:
        json.dump(manifest, handle, indent=2, sort_keys=True)
        handle.write('\n')
    return manifest_path


def read_image(path):
    """Read a colour image and return ``(bgr, error)``.

    ``error`` is a :class:`SceneError` with code ``INPUT_IMAGE_UNREADABLE``
    when OpenCV cannot decode the file.
    """
    from .types import ERROR_INPUT_IMAGE
    image = cv2.imread(path, cv2.IMREAD_COLOR)
    if image is None:
        return None, SceneError(
            code=ERROR_INPUT_IMAGE,
            message='cannot decode image: %s' % path,
            stage='input',
            context={'path': path},
        )
    return image, None
